mod color;
mod formatting;

use color::{ColorConverter, HSL};
use formatting::format_cpp_defaultfloat;
use std::env;

fn parse_arg(value: &str) -> f32 {
    value
        .parse::<f32>()
        .expect("failed to parse floating-point argument")
}

fn main() {
    let args: Vec<String> = env::args().collect();

    let mut h1 = 30.0f32;
    let mut s1 = 0.6f32;
    let mut l1 = 0.5f32;
    let mut h2 = 210.0f32;
    let mut s2 = 0.4f32;
    let mut l2 = 0.7f32;

    if args.len() > 5 {
        h1 = parse_arg(&args[1]);
        s1 = parse_arg(&args[2]);
        l1 = parse_arg(&args[3]);
        h2 = parse_arg(&args[4]);
        s2 = parse_arg(&args[5]);
    }

    if args.len() > 6 {
        l2 = parse_arg(&args[6]);
    }

    let hsl1 = HSL::new(h1, s1, l1);
    let hsl2 = HSL::new(h2, s2, l2);

    let hue_diff = ColorConverter::hue_difference(hsl1, hsl2);

    println!("{}", format_cpp_defaultfloat(hue_diff));
}

