const DEFAULT_PRECISION: usize = 6;

pub fn format_cpp_defaultfloat(value: f32) -> String {
    if value.is_nan() {
        return String::from("nan");
    }

    if value.is_infinite() {
        return if value.is_sign_negative() {
            String::from("-inf")
        } else {
            String::from("inf")
        };
    }

    if value == 0.0 {
        return if value.is_sign_negative() {
            String::from("-0")
        } else {
            String::from("0")
        };
    }

    let sign = if value.is_sign_negative() { "-" } else { "" };
    let magnitude = f64::from(value).abs();

    // std::cout uses defaultfloat with six significant digits.
    let scientific = format!("{:.*e}", DEFAULT_PRECISION - 1, magnitude);
    let (mantissa, exponent_part) = scientific
        .split_once('e')
        .expect("scientific formatting must contain an exponent");
    let exponent = exponent_part
        .parse::<i32>()
        .expect("scientific exponent must parse");

    if exponent < -4 || exponent >= DEFAULT_PRECISION as i32 {
        let trimmed = trim_fractional_zeros(mantissa);
        format!("{sign}{trimmed}e{}", format_exponent(exponent))
    } else {
        let digits_after_decimal =
            (DEFAULT_PRECISION as i32 - (exponent + 1)).max(0) as usize;
        let fixed = format!("{:.*}", digits_after_decimal, magnitude);
        let trimmed = trim_fractional_zeros(&fixed);
        format!("{sign}{trimmed}")
    }
}

fn trim_fractional_zeros(text: &str) -> String {
    if !text.contains('.') {
        return text.to_string();
    }

    let trimmed = text.trim_end_matches('0').trim_end_matches('.');
    trimmed.to_string()
}

fn format_exponent(exponent: i32) -> String {
    let sign = if exponent < 0 { '-' } else { '+' };
    let magnitude = exponent.abs();

    if magnitude < 10 {
        format!("{sign}0{magnitude}")
    } else {
        format!("{sign}{magnitude}")
    }
}
